code:
  language: csharp
  harness: statements
  source: |
    var bag = new CountingBag();
    bag.AddRange(new[] { "a", "b", "c" });
    Console.WriteLine(bag.AddedCount);

    class Bag
    {
        private readonly List<string> _items = new();

        public virtual void Add(string item) => _items.Add(item);

        public virtual void AddRange(IEnumerable<string> items)
        {
            foreach (string item in items)
            {
                Add(item);
            }
        }
    }

    class CountingBag : Bag
    {
        public int AddedCount { get; private set; }

        public override void Add(string item)
        {
            AddedCount++;
            base.Add(item);
        }

        public override void AddRange(IEnumerable<string> items)
        {
            AddedCount += items.Count();
            base.AddRange(items);
        }
    }
bugLineSets: [[32]]
fixedSource: |
  var bag = new CountingBag(new Bag());
  bag.AddRange(new[] { "a", "b", "c" });
  Console.WriteLine(bag.AddedCount);

  class Bag
  {
      private readonly List<string> _items = new();

      public virtual void Add(string item) => _items.Add(item);

      public virtual void AddRange(IEnumerable<string> items)
      {
          foreach (string item in items)
          {
              Add(item);
          }
      }
  }

  class CountingBag
  {
      private readonly Bag _inner;

      public CountingBag(Bag inner) => _inner = inner;

      public int AddedCount { get; private set; }

      public void Add(string item)
      {
          AddedCount++;
          _inner.Add(item);
      }

      public void AddRange(IEnumerable<string> items)
      {
          List<string> list = items.ToList();
          AddedCount += list.Count;
          _inner.AddRange(list);
      }
  }
fixedExpect: { kind: output, value: "3" }
